"""Compare old and installed drawings at identical live gameplay scales."""
from pathlib import Path
import json,re,collections
from mugen_sff import Sff
R=Path(__file__).resolve().parents[1];G=R/'sprite-fighter';O=G/'proportions-v9';O.mkdir(exist_ok=True);(O/'sprites').mkdir(exist_ok=True);data=[]
measure={r['slug']:r for r in json.loads((R/'.tmp/size-redesign/measurements.json').read_text())}
for slug,engine,name,group,walk in [('lloyd','lloyd','Lloyd Frontera',62000,64150),('jin-mori','jin_mori','Jin Mori',62000,64150),('jin-mori','jin_mori','Jin Mori / Monkey King',62300,64151)]:
 a=G/'characters'/slug/'art/proportions-v9';report=json.loads((a/'installation.json').read_text());n=G/'engine/ikemen-go-v1.0.0/chars'/engine;r=measure[slug];air=(n/r['files']['anim']).read_text(encoding='cp1252');scales={}
 for line in air.splitlines():
  if re.match(r'^\s*\d+\s*,\s*\d+\s*,',line):
   f=[v.strip() for v in line.split(';')[0].split(',')];scales.setdefault(tuple(map(int,f[:2])),[]).append(float(f[8]) if len(f)>8 and f[8] else 1)
 item=dict(name=name,slug=slug,target=r['world_height'],before=[],after=[])
 for version,folder in [('before',a/'before'),('after',n)]:
  s=Sff(folder/r['files']['sprite'])
  for i,key in enumerate([(group,0)]+[(walk,i) for i in range(8)]):
   im=s.decode(s.keys[key]);h=s.headers[s.keys[key]];p=f'{slug}-{group}-{version}-{i}.png';im.save(O/'sprites'/p);scale=collections.Counter(scales[key]).most_common(1)[0][0]*r['cns_scale'][1]*320/r['width']
   item[version].append(dict(file='sprites/'+p,axis=h[4:6],scale=scale))
 data.append(item)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lloyd and Mori proportion redesigns</title><style>body{background:#111922;color:#edf0f4;font:16px system-ui;margin:0}main{max-width:1120px;margin:auto;padding:24px}a{color:#9dddff}section{background:#1b2937;border:1px solid #40586b;border-radius:12px;padding:18px;margin:24px 0}canvas{width:100%;max-width:950px;background:#16212e}button,select{font:inherit;padding:7px;margin:5px}img{max-width:100%}small{color:#b9c9d5}summary{cursor:pointer;padding:10px}h1{font-size:28px}</style><main><h1>Lloyd and Jin Mori: longer, leaner proportions</h1><p>Smaller heads, longer limbs and slimmer silhouettes throughout the full pose banks and walk cycles. Lloyd stays at 53 world units; both Mori forms stay at 52. The comparisons use the same scale and foot baseline.</p><p><a href="../size-fix-v8/review.html">Full roster size review</a> · <a href="../roster.html">Manga vs Manhwa</a></p><button id="pause">Pause</button><button id="step">Next pose</button><button id="flip">Face left</button><select id="mode"><option value="walk">Walk cycle</option><option value="stand">Standing</option></select><div id="cards"></div>SHEETS<p>Built-in imagegen redraws. Exact prompts and installation checks are linked above. Gameplay files are byte-identical; controls, damage, frame timing and collision boxes are preserved. Recordings remain deferred.</p></main><script>const data=DATA,cache={};function image(p){if(!cache[p]){let im=new Image;im.src=p;cache[p]=im}return cache[p]}for(const a of data){for(const v of ['before','after'])a[v].forEach(f=>image(f.file));let s=document.createElement('section');s.innerHTML='<h2>'+a.name+'</h2><p>Before (left) · Installed redesign (right)</p><canvas width="950" height="330"></canvas>';document.querySelector('#cards').append(s);a.canvas=s.querySelector('canvas')}let frame=0,paused=false,flip=false,last=0;document.querySelector('#pause').onclick=()=>{paused=!paused;document.querySelector('#pause').textContent=paused?'Play':'Pause'};document.querySelector('#step').onclick=()=>{paused=true;document.querySelector('#pause').textContent='Play';frame=(frame+1)%8};document.querySelector('#flip').onclick=()=>{flip=!flip};function draw(t){if(!paused&&t-last>100){frame=(frame+1)%8;last=t}const i=document.querySelector('#mode').value==='stand'?0:frame+1;for(const a of data){const c=a.canvas.getContext('2d');c.clearRect(0,0,950,330);c.strokeStyle='#7594ad';c.beginPath();c.moveTo(0,295);c.lineTo(950,295);c.stroke();for(const [v,x]of [['before',235],['after',710]]){let f=a[v][i],im=image(f.file);if(!im.complete||!im.naturalWidth)continue;c.save();c.translate(x,295);if(flip)c.scale(-1,1);const z=f.scale*4.5;c.drawImage(im,-f.axis[0]*z,-f.axis[1]*z,im.width*z,im.height*z);c.restore()}}requestAnimationFrame(draw)}requestAnimationFrame(draw);</script></html>'''
sections=[]
for slug in ['lloyd','jin-mori']:
 a=G/'characters'/slug/'art/proportions-v9';report=json.loads((a/'installation.json').read_text());base='../characters/'+slug+'/art/proportions-v9/'
 sections.append('<section><h2>'+slug.replace('-',' ').title()+' full artwork</h2><a href="'+base+'installation.json">Installation checks</a> · <a href="'+base+'requests.json">Exact prompt set</a>'+''.join('<details><summary>'+kind+'</summary><img loading="lazy" src="'+base+kind+'.png" alt="'+slug+' '+kind+' redesigned animation sheet"></details>' for kind in report['sheets'])+'</section>')
(O/'review.html').write_text(html.replace('DATA',json.dumps(data)).replace('SHEETS',''.join(sections)),encoding='utf-8');(O/'review-data.json').write_text(json.dumps(data,indent=2));print('PROPORTIONS_REVIEW_BUILT',len(data),'body variants')
